import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { DomSanitizer } from '@angular/platform-browser';
import { Router } from '@angular/router';
import { AlertController, LoadingController, ToastController } from '@ionic/angular';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { Urls } from 'src/app/core/common/Urls';
import { CourseService } from 'src/app/data/service/course/course.service';
import { SliderService } from 'src/app/data/service/site/Slider.service';
import { VehicleProfile, VehicleProfileStore } from '../vehicle-profile/vehicle-profile.store';

interface TurboMatchPoint {
  rpm: number;
  pressureRatio: number;
  correctedFlowLbMin: number;
  state: 'safe' | 'surge' | 'choke' | 'over-pressure';
  x: number;
  y: number;
}

@Component({
  selector: 'app-turbo-match',
  templateUrl: './turbo-match.component.html',
  styleUrls: ['./turbo-match.component.scss'],
})
export class TurboMatchComponent implements OnInit {

  isShow = false;
  isCheck = true;
  profiles: VehicleProfile[] = [];
  selectedProfileId = '';
  profileNotice = '';
  private loadedProfileUpdatedAt = '';
  form: FormGroup;
  points: TurboMatchPoint[] = [];
  mapMaxFlow = 60;
  mapMaxPressureRatio = 3;
  peakFlowLbMin = 0;
  targetPressureRatio = 0;
  selectedPointIndex = -1;
  warning = '';

  readonly mapWidth = 640;
  readonly mapHeight = 360;
  readonly plotLeft = 58;
  readonly plotRight = 24;
  readonly plotTop = 22;
  readonly plotBottom = 46;

  constructor(private fb: FormBuilder,
    private router: Router,
    public alertController: AlertController,
    private sanitizer: DomSanitizer,
    public loadingController: LoadingController,
    public toastController: ToastController,
    private courseService: CourseService,
    private siteService: SliderService) {

    this.isShow = false;
    this.check();
  }

  ngOnInit(): void {
    this.form = this.fb.group({
      displacementLiters: [1.6, [Validators.required, Validators.min(0.1)]],
      rpmStart: [2500, [Validators.required, Validators.min(500), Validators.max(15000)]],
      rpmEnd: [7500, [Validators.required, Validators.min(500), Validators.max(15000)]],
      volumetricEfficiencyPct: [95, [Validators.required, Validators.min(20), Validators.max(160)]],
      boostPsi: [14.5, [Validators.required, Validators.min(0), Validators.max(80)]],
      ambientPressurePsi: [14.7, [Validators.required, Validators.min(5), Validators.max(20)]],
      inletAirTempC: [25, [Validators.required, Validators.min(-40), Validators.max(100)]],
      compressorSurgeLbMin: [12, [Validators.required, Validators.min(0.1)]],
      compressorMaxFlowLbMin: [44, [Validators.required, Validators.min(1)]],
      compressorMaxPressureRatio: [3.0, [Validators.required, Validators.min(1.01)]],
    });
    this.profiles = VehicleProfileStore.list();
    const active = VehicleProfileStore.active();
    if (active) { this.applyProfile(active.id); }

    this.form.valueChanges.subscribe(() => this.calculate());
    this.calculate();
  }

  ionViewWillEnter(): void {
    this.profiles = VehicleProfileStore.list();
    const active = VehicleProfileStore.active();
    if (active && this.form && (active.id !== this.selectedProfileId ||
      active.updatedAt !== this.loadedProfileUpdatedAt)) {
      this.applyProfile(active.id);
    }
  }

  applyProfile(id: string): void {
    const profile = this.profiles.find(item => item.id === id);
    if (!profile || !this.form) { return; }
    const values = VehicleProfileStore.toolValues(profile, 'turbo-match');
    let applied = 0;
    Object.keys(values).forEach(key => {
      const control = this.form.get(key);
      if (!control) { return; }
      const previous = control.value;
      control.setValue(values[key], { emitEvent: false });
      if (control.invalid) { control.setValue(previous, { emitEvent: false }); }
      else { applied++; }
    });

    this.form.updateValueAndValidity();
    this.profileNotice = `${applied} مقدار از پروفایل اعمال شد؛ سایر ورودی‌ها پیش‌فرض ابزارند.`;
    this.selectedProfileId = id;
    this.loadedProfileUpdatedAt = profile.updatedAt;
    try { VehicleProfileStore.select(id); } catch { /* Local storage may be disabled. */ }
    this.calculate();
  }

  async check() {

    SharedIonic.loading(this.loadingController);

    this.siteService.GetTunerPlusById(33).subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {

          if (res.data.isActive) {

            if (!res.data.isFree) {

              this.courseService.GetUserCoursesId().subscribe(
                ress => {
                  if (ress.status === GResponse.SuccessStatus) {
                    let found = false;
                    res.data.courseIds.forEach(courseId => {

                      if (ress.data.find(n => n == courseId)) {
                        found = true;

                        this.courseService.GetUserTunerPlusAccess().subscribe(
                          resss => {
                            if (resss.status === GResponse.SuccessStatus) {

                              SharedIonic.dismissLoading(this.loadingController);
                              this.isCheck = false;
                              this.isShow = true;
                            } else {
                              this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                              SharedIonic.dismissLoading(this.loadingController);
                            }
                          },
                          errs => {
                            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                            SharedIonic.dismissLoading(this.loadingController);
                          }
                        );
                      }
                    });

                    if (!found) {
                      this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                      SharedIonic.dismissLoading(this.loadingController);
                    }

                  } else {
                    this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                    SharedIonic.dismissLoading(this.loadingController);
                  }
                },
                errs => {
                  this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                  SharedIonic.dismissLoading(this.loadingController);
                }
              );
            } else {
              SharedIonic.dismissLoading(this.loadingController);
              this.isCheck = false;
              this.isShow = true;
            }
          } else {
            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
            SharedIonic.dismissLoading(this.loadingController);
          }
        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      err => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  calculate(): void {
    if (this.form.invalid) {
      this.points = [];
      this.selectedPointIndex = -1;
      this.warning = 'ورودی‌ها را بررسی کنید.';
      return;
    }

    const value = this.form.getRawValue();
    const rpmStart = Number(value.rpmStart);
    const rpmEnd = Number(value.rpmEnd);
    const surgeFlow = Number(value.compressorSurgeLbMin);
    const maxFlow = Number(value.compressorMaxFlowLbMin);
    const maxPressureRatio = Number(value.compressorMaxPressureRatio);

    if (rpmEnd <= rpmStart || maxFlow <= surgeFlow) {
      this.points = [];
      this.selectedPointIndex = -1;
      this.warning = 'دور پایان باید از دور شروع بیشتر و دبی بیشینه کمپرسور از دبی surge بزرگ‌تر باشد.';
      return;
    }

    const pressureRatio = (Number(value.boostPsi) + Number(value.ambientPressurePsi)) / Number(value.ambientPressurePsi);
    this.targetPressureRatio = pressureRatio;
    const rpmStep = Math.max(250, Math.round((rpmEnd - rpmStart) / 10 / 250) * 250);
    const operatingPoints: TurboMatchPoint[] = [];

    for (let rpm = rpmStart; rpm <= rpmEnd; rpm += rpmStep) {
      const correctedFlowLbMin = this.calculateCorrectedFlow(rpm, value, pressureRatio);
      const state = this.getState(correctedFlowLbMin, pressureRatio, surgeFlow, maxFlow, maxPressureRatio);
      operatingPoints.push({ rpm, pressureRatio, correctedFlowLbMin, state, x: 0, y: 0 });
    }

    if (operatingPoints[operatingPoints.length - 1]?.rpm !== rpmEnd) {
      const correctedFlowLbMin = this.calculateCorrectedFlow(rpmEnd, value, pressureRatio);
      operatingPoints.push({
        rpm: rpmEnd,
        pressureRatio,
        correctedFlowLbMin,
        state: this.getState(correctedFlowLbMin, pressureRatio, surgeFlow, maxFlow, maxPressureRatio),
        x: 0,
        y: 0,
      });
    }

    this.mapMaxFlow = Math.ceil(Math.max(maxFlow * 1.12, ...operatingPoints.map(point => point.correctedFlowLbMin * 1.12)) / 5) * 5;
    this.mapMaxPressureRatio = Math.ceil(Math.max(maxPressureRatio * 1.12, pressureRatio * 1.12) * 10) / 10;
    this.points = operatingPoints.map(point => ({
      ...point,
      x: this.toX(point.correctedFlowLbMin),
      y: this.toY(point.pressureRatio),
    }));
    this.peakFlowLbMin = Math.max(...this.points.map(point => point.correctedFlowLbMin));
    this.selectedPointIndex = this.selectedPointIndex < 0
      ? this.points.length - 1
      : Math.min(this.selectedPointIndex, this.points.length - 1);
    this.warning = this.buildWarning(pressureRatio, surgeFlow, maxFlow, maxPressureRatio);
  }

  get selectedPoint(): TurboMatchPoint | undefined {
    return this.points[this.selectedPointIndex];
  }

  get safePointCount(): number {
    return this.points.filter(point => point.state === 'safe').length;
  }

  selectPoint(index: number): void {
    if (Number.isFinite(index) && index >= 0 && index < this.points.length) {
      this.selectedPointIndex = index;
    }
  }

  stateLabel(state: TurboMatchPoint['state']): string {
    const labels = {
      safe: 'داخل محدوده',
      surge: 'زیر مرز Surge',
      choke: 'بالاتر از مرز Choke',
      'over-pressure': 'بالاتر از سقف PR',
    };
    return labels[state];
  }

  get path(): string {
    return this.points.map((point, index) => `${index === 0 ? 'M' : 'L'} ${point.x} ${point.y}`).join(' ');
  }

  get xTicks(): number[] {
    return this.buildTicks(this.mapMaxFlow, this.niceTickStep(this.mapMaxFlow / 6));
  }

  get yTicks(): number[] {
    const step = this.niceTickStep((this.mapMaxPressureRatio - 1) / 5);
    return [1, ...this.buildTicks(this.mapMaxPressureRatio, step).filter(value => value > 1)];
  }

  toX(flow: number): number {
    return this.plotLeft + flow / this.mapMaxFlow * this.plotWidth;
  }

  toY(pressureRatio: number): number {
    return this.plotTop + (this.mapMaxPressureRatio - pressureRatio) / (this.mapMaxPressureRatio - 1) * this.plotHeight;
  }

  reset(): void {
    this.form.reset({
      displacementLiters: 1.6,
      rpmStart: 2500,
      rpmEnd: 7500,
      volumetricEfficiencyPct: 95,
      boostPsi: 14.5,
      ambientPressurePsi: 14.7,
      inletAirTempC: 25,
      compressorSurgeLbMin: 12,
      compressorMaxFlowLbMin: 44,
      compressorMaxPressureRatio: 3,
    });
  }

  async onInfo(type: string): Promise<void> {
    const messages: Record<string, string> = {
      displacement: 'حجم کل موتور برحسب لیتر.', rpm: 'بازه دوری که می‌خواهید نقطه کاری توربو در آن بررسی شود.',
      ve: 'راندمان حجمی تقریبی موتور در WOT. مقدار حاصل از داینو یا دیتالاگ دقیق‌تر است.',
      boost: 'بوست هدف، برحسب psi گیج؛ یعنی فشار بالاتر از فشار محیط.',
      ambient: 'فشار مطلق محیط. در سطح دریا حدود 14.7 psi است و با ارتفاع کاهش می‌یابد.',
      temperature: 'دمای هوای ورودی به کمپرسور، نه دمای پس از اینترکولر.',
      surge: 'کمترین دبی پایدار کمپرسور از روی نقشه همان توربو. پایین‌تر از آن احتمال surge وجود دارد.',
      choke: 'بیشترین دبی قابل‌استفاده کمپرسور از روی نقشه همان توربو. بالاتر از آن راندمان و توان افت می‌کند.',
      pr: 'حداکثر pressure ratio مجاز کمپرسور از دیتاشیت یا کمپرسورمپ.',
    };
    await this.presentInfo(messages[type] || 'توضیحی برای این پارامتر موجود نیست.');
  }

  private async presentInfo(message: string): Promise<void> {
    const alert = await this.alertController.create({ cssClass: 'main-alert', header: 'توضیحات', message, buttons: ['بستن'] });
    await alert.present();
  }

  get plotWidth(): number { return this.mapWidth - this.plotLeft - this.plotRight; }
  get plotHeight(): number { return this.mapHeight - this.plotTop - this.plotBottom; }

  private calculateCorrectedFlow(rpm: number, value: Record<string, number>, pressureRatio: number): number {
    // Four-stroke inlet volume, converted to inlet-equivalent mass flow. The
    // correction follows standard compressor-map reference conditions: 68°F
    // (528°R) and 14.696 psi.
    const engineCfm = Number(value.displacementLiters) * rpm / 2 * Number(value.volumetricEfficiencyPct) / 100 * 0.0353147;
    const inletTempKelvin = Number(value.inletAirTempC) + 273.15;
    const inletDensityKgM3 = Number(value.ambientPressurePsi) * 6894.76 / (287.05 * inletTempKelvin);
    const actualMassFlowLbMin = engineCfm * pressureRatio / 35.3147 * inletDensityKgM3 * 2.20462;
    const correctedTemperatureFactor = Math.sqrt((Number(value.inletAirTempC) * 9 / 5 + 491.67) / 528);
    const correctedPressureFactor = 14.696 / Number(value.ambientPressurePsi);
    return this.round(actualMassFlowLbMin * correctedTemperatureFactor * correctedPressureFactor, 2);
  }

  private getState(flow: number, pressureRatio: number, surgeFlow: number, maxFlow: number, maxPressureRatio: number): TurboMatchPoint['state'] {
    if (pressureRatio > maxPressureRatio) { return 'over-pressure'; }
    if (flow < surgeFlow) { return 'surge'; }
    if (flow > maxFlow) { return 'choke'; }
    return 'safe';
  }

  private buildWarning(pressureRatio: number, surgeFlow: number, maxFlow: number, maxPressureRatio: number): string {
    const states = this.points.map(point => point.state);
    if (pressureRatio > maxPressureRatio) { return 'Pressure ratio هدف از محدوده‌ی کمپرسور بیشتر است.'; }
    if (states.includes('surge')) { return `بخشی از منحنی زیر مرز surge (${surgeFlow} lb/min) قرار دارد.`; }
    if (states.includes('choke')) { return `بخشی از منحنی از دبی بیشینه (${maxFlow} lb/min) عبور می‌کند.`; }
    return 'تمام نقاط محاسبه‌شده در محدوده‌ی تعریف‌شده‌ی کمپرسور قرار دارند.';
  }

  private buildTicks(max: number, step: number): number[] {
    const ticks: number[] = [];
    for (let value = 0; value <= max; value += step) { ticks.push(Number(value.toFixed(3))); }
    return ticks;
  }

  private niceTickStep(raw: number): number {
    const magnitude = Math.pow(10, Math.floor(Math.log10(raw)));
    const scaled = raw / magnitude;
    const rounded = scaled <= 1 ? 1 : scaled <= 2 ? 2 : scaled <= 5 ? 5 : 10;
    return rounded * magnitude;
  }

  private round(value: number, decimals: number): number {
    const factor = Math.pow(10, decimals);
    return Math.round((value + Number.EPSILON) * factor) / factor;
  }
}
